  ],
  "events": [
    {
      "trigger": "formed",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Tropical Depression Thirteen"],
        "Location": ["southwestern Caribbean Sea"],
        "Content": ["from a tropical wave that exited Africa on October 10"]
      }
    },
    {
      "trigger": "intensified",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["it"],
        "Content": ["into tropical storm mitch"]
      }
    },
    {
      "trigger": "intensified",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Content": ["in response to improving conditions which included warm waters and good outflow"]
      }
    },
    {
      "trigger": "became",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["It"],
        "Content": ["a hurricane on October 24 and developed an eye"]
      }
    },
    {
      "trigger": "intensified",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Content": ["first into a major hurricane on October 25 and then into a Category 5 on the Saffir-Simpson Hurricane Scale the next day"]
      }
    },
    {
      "trigger": "maintained",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["mitch"],
        "Content": ["maximum sustained winds of 180 mph ( 285 km/h ) while off the northern coast of honduras"]
      }
    },
    {
      "trigger": "reported",
      "type": "Statement",
      "arguments": {
        "Speaker": ["Hurricane Hunters"],
        "Message": ["a minimum barometric pressure of 905 mbar , which at the time was the lowest in the month of October and tied for the fourth lowest for any Atlantic hurricane"]
      }
    },
    {
      "trigger": "anticipated",
      "type": "Statement",
      "arguments": {
        "Speaker": ["the National Hurricane Center ( NHC ) and various tropical cyclone forecast models"],
        "Message": ["a turn to the north , threatening the Yucatán Peninsula"]
      }
    },
    {
      "trigger": "turned",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Content": ["to the south due to a ridge that was not observed while the storm was active"]
      }
    },
    {
      "trigger": "made landfall",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["the hurricane"],
        "Location": ["Honduras"],
        "Content": ["on October 29 with winds of 80 mph ( 130 km/h )"]
      }
    },
    {
      "trigger": "weakened",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Content": ["over land and maintained deep convection over adjacent waters"]
      }
    },
    {
      "trigger": "dissipated",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["the surface circulation of Mitch"],
        "Location": ["Central America"],
        "Content": ["on November 1"]
      }
    },
    {
      "trigger": "reached",
      "type": "Arriving",
      "arguments": {
        "Agent": ["the remnants"],
        "Location": ["the Gulf of Mexico"]
      }
    },
    {
      "trigger": "reorganized",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["the remnants"],
        "Content": ["into a tropical storm on November 3"]
      }
    },
    {
      "trigger": "accelerated",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Content": ["to the northeast ahead of a cold front , moving across the Yucatán Peninsula before striking southwestern Florida on November 5"]
      }
    },
    {
      "trigger": "striking",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["Mitch"],
        "Location": ["southwestern Florida"],
        "Content": ["on November 5"]
      }
    },
    {
      "trigger": "became",
      "type": "Catastrophe",
      "arguments": {
        "Patient": ["the storm"],
        "Content": ["an extratropical cyclone , which was tracked by the NHC until November 9"]
      }
    }
  ]
}
